/** Open/closed/overdue counters plus the last write, for the project card. */
export async function getProjectStats(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ProjectStats> {
  const db = getDb();
  const scope = and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.projectId, projectId),
    ...compact(livePredicate(issues.archivedAt, {})),
  );

  const closed = db
    .select({ value: count() })
    .from(issues)
    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
    .get();

  const all = db.select({ value: count() }).from(issues).where(scope).get();

  const overdue = db
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        scope,
        isNotNull(issues.dueAt),
        lt(issues.dueAt, toIsoTimestamp(new Date())),
      ),
    )
    .get();

  const lastActivity = db
    .select({ value: sql<string | null>`max(${issues.updatedAt})` })
    .from(issues)
    .where(scope)
    .get();

  const closedCount = closed?.value ?? 0;

  return {
    projectId,
    openIssues: (all?.value ?? 0) - closedCount,
    closedIssues: closedCount,
    overdueIssues: overdue?.value ?? 0,
    lastActivityAt:
      lastActivity?.value == null ? null : toIsoTimestamp(lastActivity.value),
  };
}

/**
 * Result envelope every job returns to the scheduler.
 */
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

export type JobResult = {
  kind: string;
  processed: number;
  failed: number;
  durationMs: number;
  startedAt: IsoTimestamp;
};

/** The zero value a job starts from and mutates as it works. */
export function emptyJobResult(
  kind: string,
  startedAt: IsoTimestamp,
): JobResult {
  return { kind, processed: 0, failed: 0, durationMs: 0, startedAt };
}

/**
 * Convenience for a job body: stamps the start, runs the work and fills in
 * `durationMs`. Kept here so every job reports the same shape.
 */
export async function runJob(
  kind: string,
  work: (result: JobResult) => Promise<void>,
): Promise<JobResult> {
  const startedAt = toIsoTimestamp(new Date());
  const began = Date.now();
  const result = emptyJobResult(kind, startedAt);

  await work(result);

  return { ...result, durationMs: Date.now() - began };
}

/**
 * Recomputes `organization_usage` so plan-limit checks stay accurate after bulk changes.
 *
 * Must call (do not reimplement): recomputeUsage
 */
import { createLogger } from "@/lib/logger";
import * as usageRepo from "@/server/repositories/usage-repository";
import { recomputeUsage } from "@/server/services/usage-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

/** Organizations recounted per pass; the list is oldest-measured first. */
const ORG_BATCH = 25;

const logger = createLogger("usage-rollup-job");

/**
 * The correction pass for the incremental deltas `UsageService` applies on the
 * write path. Those deltas are cheap but drift — an aborted transaction, a
 * cascade that archived more rows than the event reported — and a quota check
 * is only as trustworthy as the counter behind it.
 */
export async function runUsageRollupJob(now: Date): Promise<JobResult> {
  return runJob("usage-rollup", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      try {
        const usage = await recomputeUsage(orgId);
        result.processed += 1;

        logger.debug("usage recomputed", {
          orgId,
          seats: usage.seatsUsed,
          projects: usage.projectsUsed,
          issues: usage.issuesUsed,
          at: now.toISOString(),
        });
      } catch (error) {
        result.failed += 1;
        logger.error("usage rollup failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
